using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;
namespace BackendPRO {public static class BackendBuilder {
[MenuItem("Tools/Backend PRO/Create Login Scene")]
static void Build(){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);var root=new GameObject("Backend Login",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var scaler=root.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);var auth=root.AddComponent<GameAuth>();var panel=root.AddComponent<LoginPanel>();panel.auth=auth;var font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
GameObject Node(string name,float y){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(root.transform,false);var rt=g.GetComponent<RectTransform>();rt.sizeDelta=new Vector2(520,65);rt.anchoredPosition=new Vector2(0,y);return g;}
Text Label(Transform parent,string value){var g=new GameObject("Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);var rt=g.GetComponent<RectTransform>();rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=new Vector2(12,0);rt.offsetMax=new Vector2(-12,0);var t=g.GetComponent<Text>();t.font=font;t.fontSize=26;t.alignment=TextAnchor.MiddleCenter;t.color=Color.white;t.text=value;return t;}
InputField Field(string name,float y,bool secret){var g=Node(name,y);g.AddComponent<Image>().color=new Color(.15f,.18f,.24f);var f=g.AddComponent<InputField>();f.textComponent=Label(g.transform,"");f.placeholder=Label(g.transform,name);if(secret)f.contentType=InputField.ContentType.Password;return f;}
void Button(string name,float y,UnityEngine.Events.UnityAction action){var g=Node(name,y);g.AddComponent<Image>().color=new Color(.35f,.27f,.14f);var btn=g.AddComponent<Button>();Label(g.transform,name);UnityEditor.Events.UnityEventTools.AddPersistentListener(btn.onClick,action);}
panel.email=Field("Email",300,false);panel.password=Field("Password",220,true);panel.securityKey=Field("Security Key",140,true);Button("Copy Key",60,panel.CopyKey);Button("Login",-20,panel.Login);Button("Register",-100,panel.Register);Button("Load Player",-180,panel.Load);Button("Logout",-260,panel.Logout);panel.status=Label(Node("Status",-360).transform,"Ready");new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));var path=AssetDatabase.GenerateUniqueAssetPath("Assets/BackendPRO/Login.unity");EditorSceneManager.SaveScene(scene,path);EditorSceneManager.CloseScene(scene,true);EditorUtility.DisplayDialog("Backend PRO","Created "+path,"OK");}
}}
